// Applies the native widget, app icons and splash screens to the Android
// project generated by `npx cap add android`.
// Usage: node tools/patch-android.js
const fs = require("fs");
const path = require("path");
const { writePng, drawBlock } = require("./make-icons");

const ROOT = path.join(__dirname, "..");
const CONFIG = JSON.parse(fs.readFileSync(path.join(ROOT, "capacitor.config.json"), "utf8"));
const PACKAGE = CONFIG.appId;
const ANDROID = path.join(ROOT, "android");
const APP = path.join(ANDROID, "app", "src", "main");

if (!fs.existsSync(ANDROID)) {
  console.error('Android project not found. Run "npx cap add android" first.');
  process.exit(1);
}

function findFile(dir, name) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      const nested = findFile(full, name);
      if (nested) return nested;
    } else if (entry.name === name) {
      return full;
    }
  }
  return null;
}

function readNative(file) {
  return fs.readFileSync(path.join(ROOT, "native", "android", "java", file), "utf8")
    .replace(/__PACKAGE__/g, PACKAGE);
}

// 1. Java sources
const packageDir = path.join(APP, "java", ...PACKAGE.split("."));
fs.mkdirSync(packageDir, { recursive: true });

for (const file of ["WidgetBridgePlugin.java", "CalendarWidgetProvider.java"]) {
  fs.writeFileSync(path.join(packageDir, file), readNative(file));
}

const mainActivity = findFile(path.join(APP, "java"), "MainActivity.java")
  || path.join(packageDir, "MainActivity.java");
fs.writeFileSync(mainActivity, readNative("MainActivity.java"));

// 2. Layouts, drawables and widget metadata
fs.cpSync(
  path.join(ROOT, "native", "android", "res"),
  path.join(APP, "res"),
  { recursive: true }
);

// 3. Launcher icons (legacy + adaptive foreground) generated from the same pixel art
const DENSITIES = { mdpi: 48, hdpi: 72, xhdpi: 96, xxhdpi: 144, xxxhdpi: 192 };
for (const [folder, size] of Object.entries(DENSITIES)) {
  const dir = path.join(APP, "res", `mipmap-${folder}`);
  fs.mkdirSync(dir, { recursive: true });
  writePng(path.join(dir, "ic_launcher.png"), size, size, drawBlock(size, 0.82, 0, "#8bd8ff"));
  writePng(path.join(dir, "ic_launcher_round.png"), size, size, drawBlock(size, 0.82, 0, "#8bd8ff"));
  const foreground = Math.round(size * 2.25);
  writePng(
    path.join(dir, "ic_launcher_foreground.png"),
    foreground,
    foreground,
    drawBlock(foreground, 0.62)
  );
}

const backgroundFile = path.join(APP, "res", "values", "ic_launcher_background.xml");
fs.writeFileSync(
  backgroundFile,
  '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">#8BD8FF</color>\n</resources>\n'
);

// 4. Splash screens: sky gradient with the centred grass block
function drawSplash(width, height) {
  const pixels = Buffer.alloc(width * height * 4);
  const top = [0x8b, 0xd8, 0xff];
  const bottom = [0xe9, 0xff, 0xd6];
  for (let y = 0; y < height; y += 1) {
    const mix = height <= 1 ? 0 : y / (height - 1);
    const r = Math.round(top[0] + (bottom[0] - top[0]) * mix);
    const g = Math.round(top[1] + (bottom[1] - top[1]) * mix);
    const b = Math.round(top[2] + (bottom[2] - top[2]) * mix);
    for (let x = 0; x < width; x += 1) {
      const index = (y * width + x) * 4;
      pixels[index] = r;
      pixels[index + 1] = g;
      pixels[index + 2] = b;
      pixels[index + 3] = 255;
    }
  }

  const block = Math.round(Math.min(width, height) * 0.42);
  const art = drawBlock(block, 0.82);
  const startX = Math.floor((width - block) / 2);
  const startY = Math.floor((height - block) / 2);
  for (let y = 0; y < block; y += 1) {
    const target = ((startY + y) * width + startX) * 4;
    art.copy(pixels, target, y * block * 4, (y + 1) * block * 4);
  }
  return pixels;
}

const SPLASHES = [
  ["drawable", 480, 320],
  ["drawable-land-mdpi", 480, 320],
  ["drawable-land-hdpi", 800, 480],
  ["drawable-land-xhdpi", 1280, 720],
  ["drawable-land-xxhdpi", 1600, 960],
  ["drawable-land-xxxhdpi", 1920, 1280],
  ["drawable-port-mdpi", 320, 480],
  ["drawable-port-hdpi", 480, 800],
  ["drawable-port-xhdpi", 720, 1280],
  ["drawable-port-xxhdpi", 960, 1600],
  ["drawable-port-xxxhdpi", 1280, 1920]
];

for (const [folder, width, height] of SPLASHES) {
  const dir = path.join(APP, "res", folder);
  fs.mkdirSync(dir, { recursive: true });
  writePng(path.join(dir, "splash.png"), width, height, drawSplash(width, height));
}

// 5. Manifest: widget receiver + boot permission
const manifestFile = path.join(APP, "AndroidManifest.xml");
let manifest = fs.readFileSync(manifestFile, "utf8");

if (!manifest.includes("CalendarWidgetProvider")) {
  const receiver = `
        <receiver
            android:name=".CalendarWidgetProvider"
            android:exported="false"
            android:label="@string/widget_label">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
                <action android:name="android.intent.action.DATE_CHANGED" />
                <action android:name="android.intent.action.TIME_SET" />
                <action android:name="android.intent.action.TIMEZONE_CHANGED" />
                <action android:name="android.intent.action.BOOT_COMPLETED" />
            </intent-filter>
            <meta-data
                android:name="android.appwidget.provider"
                android:resource="@xml/calendar_widget_info" />
        </receiver>
`;
  manifest = manifest.replace("</application>", `${receiver}    </application>`);
}

if (!manifest.includes("RECEIVE_BOOT_COMPLETED")) {
  manifest = manifest.replace(
    "</manifest>",
    '    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />\n</manifest>'
  );
}

fs.writeFileSync(manifestFile, manifest);

// 6. Widget strings
const stringsFile = path.join(APP, "res", "values", "strings.xml");
if (fs.existsSync(stringsFile)) {
  let strings = fs.readFileSync(stringsFile, "utf8");
  if (!strings.includes("widget_label")) {
    strings = strings.replace(
      "</resources>",
      '    <string name="widget_label">Календарь на сегодня</string>\n'
      + '    <string name="widget_description">План на сегодня из Пиксельного календаря</string>\n'
      + "</resources>"
    );
    fs.writeFileSync(stringsFile, strings);
  }
}

// 7. Signing: use a stable release key when CI provides keystore.properties
const gradleFile = path.join(ANDROID, "app", "build.gradle");
let gradle = fs.readFileSync(gradleFile, "utf8");

if (!gradle.includes("keystorePropertiesFile")) {
  gradle = gradle.replace(
    "apply plugin: 'com.android.application'",
    `apply plugin: 'com.android.application'

def keystorePropertiesFile = rootProject.file("keystore.properties")
def keystoreProperties = new Properties()
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}`
  );

  gradle = gradle.replace(
    "    buildTypes {",
    `    signingConfigs {
        release {
            if (keystorePropertiesFile.exists()) {
                storeFile rootProject.file(keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
                storeType 'PKCS12'
            }
        }
    }
    buildTypes {
        debug {
            if (keystorePropertiesFile.exists()) {
                signingConfig signingConfigs.release
            }
        }`
  );

  gradle = gradle.replace(
    "        release {\n            minifyEnabled false",
    `        release {
            if (keystorePropertiesFile.exists()) {
                signingConfig signingConfigs.release
            }
            minifyEnabled false`
  );

  fs.writeFileSync(gradleFile, gradle);
  console.log("Signing config injected into app/build.gradle");
} else {
  console.log("Signing config already present in app/build.gradle");
}

console.log(`Android project patched for ${PACKAGE}`);
console.log(`MainActivity: ${path.relative(ROOT, mainActivity)}`);
console.log("Widget receiver, icons and splash screens are ready.");
